/// <summary>
/// Extension of  NDXTRUMPFPDA form
/// </summary>
[ExtensionOf(formStr(NDXTRUMPFPDA))]
final class NDXTRUMPFPDA_frm_Extension
{
}

Method.Source:
/// <summary>
/// Update filter
/// </summary>
/// <param name = "_value">filter value </param>
/// <returns>filter str</returns>
public str filterUpdate(str _value)
{
    next filterUpdate(_value);

    return strScan(_value, '%', 1, strLen(_value)) ? this.buildFilterNew(_value):_value;
}

/// <summary>
/// Build new filter
/// </summary>
/// <param name = "_filterFromString">filter str</param>
/// <returns>filter str</returns>
protected str buildFilterNew(str _filterFromString)
{
    const str Delimiter1 = '%';
    const str DelimiterPA = ', ';

    str filterValue;
    str filterStr;

    container conPA;
    str productionPrefix = '';

    List filterValuesList;
    ListEnumerator filterValuesListEnumerator;
    NumberSequenceTable lNumberSequenceTable;

    //Prefix from numbersequence
    if(!lNDXTRUMPFParameters || !lNDXTRUMPFParameters.RefRecIdNumberSequenceTable)
    {
        Warning("@NDX:NDX_TRU_Warn3");
        return '';
    }

    lNumberSequenceTable = NumberSequenceTable::find(lNDXTRUMPFParameters.RefRecIdNumberSequenceTable);

    if(lNumberSequenceTable)
    {
        productionPrefix = subStr(lNumberSequenceTable.Format, 1, strScan(lNumberSequenceTable.Format, '#', 1, strLen(lNumberSequenceTable.Format)));
    }

    filterStr = _filterFromString;

    filterValuesList = strSplit(_filterFromString, Delimiter1);

    if(filterValuesList.elements() > 0)
    {
        filterValuesListEnumerator = filterValuesList.getEnumerator();

        while(filterValuesListEnumerator.moveNext())
        {
            filterValue = filterValuesListEnumerator.current();

            if(filterValue != '')
            {
                filterValue = strscan(filterValue, productionPrefix, 1, strlen(productionPrefix))? filterValue:productionPrefix + filterValue;
                conPA += filterValue;
            }
        }
        filterStr = Con2Str(conPA, DelimiterPA);
    }
    return filterStr;
}
